s=s.replace('import { ArrowLeft, Check, ShieldCheck, Upload, UserRound, Zap } from "lucide-react";', 'import { ArrowLeft, Check, Crop, ShieldCheck, Upload, UserRound, ZoomIn, Zap } from "lucide-react";',1)
s=s.replace('  const [error, setError] = useState("");', '  const [error, setError] = useState("");\n  const [photoSource, setPhotoSource] = useState<string | null>(null);\n  const [photoZoom, setPhotoZoom] = useState(1);',1)
s=s.replace('  const readProof = (key: "profilePhoto" | "diplomaProof" | "skillProof", file?: File) => { if (!file) return; const reader = new FileReader(); reader.onload = () => update(key, { name: file.name, type: file.type, data: String(reader.result) }); reader.readAsDataURL(file); };', '''  const readProof = (key: "diplomaProof" | "skillProof", file?: File) => { if (!file) return; const reader = new FileReader(); reader.onload = () => update(key, { name: file.name, type: file.type, data: String(reader.result) }); reader.readAsDataURL(file); };
  const readPhoto = (file?: File) => { if (!file || !file.type.startsWith("image/")) return; const reader = new FileReader(); reader.onload = () => { setPhotoSource(String(reader.result)); setPhotoZoom(1); }; reader.readAsDataURL(file); };
  useEffect(() => { if (!photoSource) return; const image = new Image(); image.onload = () => { const canvas = document.createElement("canvas"); canvas.width = 512; canvas.height = 512; const cropSize = Math.min(image.naturalWidth, image.naturalHeight) / photoZoom; const sx = (image.naturalWidth - cropSize) / 2; const sy = (image.naturalHeight - cropSize) / 2; canvas.getContext("2d")?.drawImage(image, sx, sy, cropSize, cropSize, 0, 0, 512, 512); update("profilePhoto", { name: "profile-photo.jpg", type: "image/jpeg", data: canvas.toDataURL("image/jpeg", 0.86) }); }; image.src = photoSource; }, [photoSource, photoZoom]);''',1)
s=s.replace('onChange={(e) => readProof("profilePhoto", e.target.files?.[0])}', 'onChange={(e) => readPhoto(e.target.files?.[0])}',1)
